  status text NOT NULL DEFAULT 'RECEIVED',
  checkpoint text NOT NULL DEFAULT 'RECEIVED',
  checkpoint_history jsonb NOT NULL DEFAULT '[]'::jsonb,
  retry_count int NOT NULL DEFAULT 0,
