  return {
    taskId: String(task.taskId ?? ''),
    traceId: String(task.traceId ?? ''),
    status: String(task.status ?? 'UNKNOWN'),
    terminal: task.terminal === true,
    checkpoint: String(task.checkpoint ?? ''),
    retryCount: Number(task.retryCount ?? 0),
